import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第四卷 退潮 · 第75章 体检","description":"","frontmatter":{},"headers":[],"relativePath":"第75章_体检.md","filePath":"第75章_体检.md"}'),r={name:"第75章_体检.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第四卷-退潮-·-第75章-体检" tabindex="-1">第四卷 退潮 · 第75章 体检 <a class="header-anchor" href="#第四卷-退潮-·-第75章-体检" aria-label="Permalink to &quot;第四卷 退潮 · 第75章 体检&quot;">​</a></h1><p>高三那个秋末，体检定在一个阴天的上午。</p><p>走廊里挤满了人，风从尽头吹进来，带着落叶微苦的气味，混着淡淡的消毒水味。大家捏着体检单，纸边被手心捂得发潮。老周站在前面喊着维持秩序，声音有些哑，让我们按顺序走，别堵在门口。</p><p>我排在男生队里，陈默在我前面，一直小声念叨害怕抽血。他回头问我，等下能不能让我先上，我在后面看着会更怕。我笑他，这会儿倒讲起顺序了。他苦着脸说，一闻到药棉的味道腿就软。</p><p>队伍慢慢往前挪，我抬头，看见了江苒。</p><p>她在女生那一列，站在窗边。淡白的日光落在她发顶，校服外套拉到顶，领口却空了一圈。风一吹，衣领轻轻晃，露出一截细细的脖子。她低头看单子，下巴线条清晰，握着纸的手腕瘦得能看见骨节。</p><p>我心头顿了一下。她瘦了。</p><p>袖口在她手上显得格外长，指尖只露出一小截。她把头发别到耳后，耳垂小小的，颜色很淡。林小满站在她身后，正探头跟她说话。她笑着点头，把单子折了又展开，眼睛弯着，可那笑里透着一股藏不住的倦。</p><p>走廊里很吵，有人背流程，有人喊饿，有人把手缩进袖子取暖。护士推着小车走过，轮子碾过地面，发出轻响。药棉气味飘过来，陈默又开始深呼吸，说不行了，我现在就想跑。我拍拍他的肩，让他盯着窗外看，别盯着针。</p><p>老周走过来，点了点名，让我们把单子拿好。我从口袋掏出折好的单子，摸到了一颗海盐糖。包装纸皱皱的，是她先前塞给我的，一直没舍得吃。糖的棱角硌着掌心，泛起一点咸甜的想象。</p><p>这时江苒似有所觉，抬头朝这边看来。目光碰上，她愣了一下，随即弯起眼睛，隔着人群朝我晃了晃手里的单子。我朝她笑笑，指指前方，示意队伍还长。她点点头，转了回去。</p><p>可我眼里的她，和记忆里不太一样了。前些天在小卖部，她还捧着热饮说天冷要多吃点，脸颊带着软软的光。现在隔着几步远，能看见她锁骨在领口若隐若现，肩线撑不起校服，整个人像被风拿走了一部分。</p><p>桂花的香从窗外飘进来，很淡。她缩了缩脖子，把手藏进袖子。林小满问她冷不冷，要不要披自己的外套。她摇头，说站一会儿就进屋了，里面暖和。声音轻轻的，飘到我这里时已经散了一半。</p><p>轮到她量身高体重，她脱鞋站上去，背挺得很直。医生看了看仪器，在单子上写字。林小满踮脚去瞅，低呼一声，说你怎么又轻了。她赶紧收起单子，笑着说秋天穿得少，称着轻。林小满皱眉，说你最近吃饭就拨几口，大家都看见了。她拉住林小满的手，低声哄了几句，才把这页翻过去。</p><p>我听着，心慢慢沉下去。食堂里她确实吃得少，饭菜拨来拨去，最后总剩很多。顾远笑她省粮食，何晓给她带点心，她也都分给大家，自己只留一小块。我原以为只是高三太累，如今看她站在秤上的单薄模样，才觉得事情没有那样简单。</p><p>队伍进了测视力的屋子，灯光亮得晃眼。陈默紧张，把左右说反，引得一阵笑。他红着脸解释，说刚才没看清。江苒那组先去了量血压处。她坐在椅子上，挽起袖子，露出细细的手臂。袖带绑上去，机器充气发出声响，她望着窗外，睫毛垂下，眼下有淡淡的影。</p><p>我站在门口，看见她腕上那根红绳。那是宋阿婆给的，如今洗得发白，系在她腕上松松地晃。她瘦得仿佛连这点重量都挂不住。心里像被轻轻揪住，不重，却一直不松。</p><p>轮到我测时，护士让我放平手臂，别乱动。我坐下，眼角余光还跟着她。她测完在整理袖口，扣子扣了两次才扣好。林小满帮她翻好领子，说你手这样凉，早上可有喝热水。她说喝了，许是走廊风大。我想起她今早杯子里满满的水，或许一口也未动。</p><p>我把自己的单子对折塞进口袋，挤到走廊尽头的热水桶边。拧开桶盖，热气一下扑到脸上，眼镜起了一层白雾，我用袖口擦了擦才看清。拿起她放在窗台上的杯子，杯身凉得像冰，拧开盖子往里倒，水线细细的，热气绕着杯口打转，带着一点铁锈的味。我把盖子拧紧，塞回她手里，指尖碰到杯壁，烫得她缩了一下又握住，她轻声说谢谢。林小满在旁边小声嘀咕，你这人倒是记得她杯子在哪。我没接话，只是看着她把杯子抱在胸前，哈出的白气混进热气里。那瞬间想起去年秋天她也是这样把我的杯子捂在手心，说别总是凉着手，心口那股被风掏空的感觉，像被热水一点点填回来。</p><p>测完我去找她，好不容易挤到她身边。她看见我眼睛亮了些，问测完了吗。我点头问她冷吗。她摇头，说屋里暖和。我看着她发白的嘴唇，把那颗糖递过去，说含着会暖一点。</p><p>她接过一看就笑了，问这颗怎还在。我说没舍得吃，现下归还。她剥开糖纸放进嘴里，腮帮鼓起一点，气色缓了些。我问好吃吗。她点头，说还是咸咸甜甜的味道。我顿了顿，轻声问，你最近可有好好吃饭。</p><p>她一怔，随即笑开，说吃了，食堂的饭都有吃。我说别哄我，衣领都撑不起来了。她下意识拉拉领口，说衣服洗松了。林小满在旁小声说，裤子都松了，还借了我的腰带。她瞪了林小满一眼，又转头看我，眼神软下来，说许是功课太累，过阵子便好。我说累更要吃，不然身体怎扛得住。她点头，说知道了，沈同学别皱眉了。</p><p>她把一张卡片夹在体检单上，卡片画着海，蓝意晕开，像退潮的浪。她说夹着压一压，纸就不卷了。我说等下一起去喝点热汤。她想了想，说好，想喝热热的汤，暖到心里那种。</p><p>护士喊下一组抽血，陈默脸色发白，拽着我的袖子不放。顾远在后面笑他。老周催我们快走，别堵路。我同江苒说了句等下见，便被人群推着向前。回头时她站在原地，含着糖朝我挥手，身影在淡光里细长，影子贴在地上，轻轻晃。</p><p>抽血处在走廊最里，药棉味更重。陈默进去时腿发抖，出来时按着棉签，倒得意起来，说也没多疼。我挽袖坐下，针尖微凉，很快便好。我按着胳膊出来，抬头去寻她。</p><p>女生组已散了，林小满独自按着胳膊站在窗边。我问江苒呢。她指指里间小屋，说医生把她留下了，要多问几句，帘子还拉着。我走过去，看见半掩的门后，帘子垂着，里面安静得只剩仪器轻响。她的体检单放在小桌上，卡片露出一角，海蓝色安静地躺着。</p><p>风从窗缝挤入，帘子轻轻摆了一下。我站在门口，忽然很想知道，帘子后面那几句话，究竟是什么。</p>',27)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
